public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        String file = sc.nextLine();
        BufferedReader br = new BufferedReader(new FileReader(file));

        int info = 0, error = 0, warn = 0;
